{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/side-checks.json
    Extras to tick: a fieldset named by its legend, one checkbox per option with its note and price. Static markup.
    Props (p): name, legend, options. -#}
{%- set v_name = (p.name ?? null) -%}
{%- set v_legend = (p.legend ?? null) -%}
{%- set v_options = (p.options ?? null) -%}
{%- set c_6 -%}
  {%- set c_1 -%}
    {{ og_text(v_legend) }}
  {%- endset -%}
  {{ include('compose/Legend.html.twig', {'size': 'sm', 'class': 'mb-2', 'children': c_1}, with_context = false) }}
  {%- for v_o in og_l(v_options) %}
    {%- set c_5 -%}
      {%- set c_3 -%}
        {{ include('compose/Checkbox.html.twig', {'name': og_s(og_tpl('{0}-{1}', [v_name, og_get(v_o, ['id'])])), 'value': 'on'}, with_context = false) }}
        {%- set c_2 -%}
          {{ og_text(og_get(v_o, ['name'])) }}
        {%- endset -%}
        {{ include('compose/Inline.html.twig', {'children': c_2}, with_context = false) }}
      {%- endset -%}
      {{ include('compose/Inline.html.twig', {'class': 'flex items-center gap-2', 'children': c_3}, with_context = false) }}
      {%- set c_4 -%}
        {{ og_text(og_tpl('{0} · {1}', [og_get(v_o, ['note']), og_money(og_get(v_o, ['price']), og_get(v_o, ['currency']))])) }}
      {%- endset -%}
      {{ include('compose/Inline.html.twig', {'class': 'text-muted-foreground', 'children': c_4}, with_context = false) }}
    {%- endset -%}
    {{ include('compose/Label.html.twig', {'class': 'flex items-center justify-between gap-4 rounded px-4 py-2 text-sm inset-ring inset-ring-border has-checked:bg-muted', 'children': c_5}, with_context = false) }}
  {%- endfor %}
{%- endset -%}
{{ include('compose/Fieldset.html.twig', {'class': 'flex flex-col gap-2', 'attrs': og_attrs(['data-testid', 'sides']), 'children': c_6}, with_context = false) }}
